// Parametr init kontekstu - wspolny dla calej aplikacji,
// ustawiany PRZED startem, jednakowy dla wszystkich serwletow.
context.addParameter("appName", "JavaQuest Sklep Demo");

// Odczyt w DOWOLNYM serwlecie tej aplikacji:
ServletContext ctx = getServletContext();
String appName = ctx.getInitParameter("appName");

// VisitCounterServlet (/odwiedz) inkrementuje atrybut kontekstu.
// StatsServlet (/statystyki) - INNA klasa - tylko go odczytuje,
// a mimo to widzi TA SAMA wartosc, bo obaj wspoldziela ten sam
// ServletContext.

ServletContext ctx = getServletContext();
synchronized (ctx) {
    Integer liczba = (Integer) ctx.getAttribute("liczbaOdwiedzin");
    if (liczba == null) liczba = 0;
    liczba++;
    ctx.setAttribute("liczbaOdwiedzin", liczba);
}
// W INNYM serwlecie: Integer liczba = (Integer) getServletContext().getAttribute("liczbaOdwiedzin");
